// ═══════════════════════════════════════════════════════════
// IBJA Rate Parser v4 — left-table-first, structure-aware
//
// Logic:
//  1. Prefer the LEFT "current day" table (id=TodayRatesTableDataYes).
//     Per metal: use PM span if non-empty, else AM span.
//  2. If the left table has no data, fall back to the
//     "Previous Dates Rate" table — PM pane preferred, else AM pane,
//     taking the FIRST row (latest date).
// ═══════════════════════════════════════════════════════════
const item = $input.first();

// Extract raw HTML from wherever n8n put it
let html = '';
if (typeof item.json === 'string') {
  html = item.json;
} else if (typeof item.json.data === 'string') {
  html = item.json.data;
} else if (typeof item.json.body === 'string') {
  html = item.json.body;
} else if (typeof item.json.response === 'string') {
  html = item.json.response;
} else {
  html = JSON.stringify(item.json);
}
console.log('HTML length:', html.length);

const METALS = [
  { id: 'Gold999',   key: 'gold_999'   },
  { id: 'Gold995',   key: 'gold_995'   },
  { id: 'Gold916',   key: 'gold_916'   },
  { id: 'Gold750',   key: 'gold_750'   },
  { id: 'Gold585',   key: 'gold_585'   },
  { id: 'Silver999', key: 'silver_999' }
];

const toNum = (s) => {
  if (s == null) return null;
  const n = parseInt(String(s).replace(/[^\d]/g, ''), 10);
  return Number.isFinite(n) && n > 0 ? n : null;
};

// Read inner text of <span id="...">VALUE</span>
const readSpan = (id) => {
  const re = new RegExp('id="' + id + '"\\s*>([^<]*)<', 'i');
  const m = html.match(re);
  return m ? m[1].trim() : '';
};

// Date anchor from the "Previous 30 Days" PDF link: Pdf_xxx_YYYYMMDD...
const pdfDateAnchor = () => {
  const m = html.match(/Pdf_\d+_(\d{4})(\d{2})(\d{2})\d*/);
  return m ? `${m[1]}-${m[2]}-${m[3]}` : null;
};

// ─── STRATEGY 1: left "today" table, PM preferred per metal, else AM ───
const parseTodayTable = () => {
  if (html.indexOf('TodayRatesTableDataYes') === -1) return null;
  const metals = {};
  let usedPM = false;
  for (const m of METALS) {
    const pm = toNum(readSpan('lbl' + m.id + '_PM'));
    const am = toNum(readSpan('lbl' + m.id + '_AM'));
    if (pm != null) { metals[m.key] = pm; usedPM = true; }
    else { metals[m.key] = am; }
  }
  // Require at least gold_999 + silver_999, else the left table is empty
  if (metals.gold_999 == null || metals.silver_999 == null) return null;
  return {
    source: 'ibjarates.com (today)',
    dateISO: pdfDateAnchor(),
    sessionLabel: usedPM ? 'PM' : 'AM',
    metals
  };
};

// ─── STRATEGY 2: Previous Dates table, latest (first) row of given pane ───
const parsePreviousDates = (paneId) => {
  const start = html.indexOf('id="' + paneId + '"');
  if (start === -1) return null;
  // pane ends at the NEXT pane (id="tab-..."), not this one's own class attr
  const next = html.indexOf('id="tab-', start + 1);
  const end = next === -1 ? html.length : next;
  const pane = html.substring(start, end);

  const rowMatch = pane.match(/<strong>\s*(\d{2})\/(\d{2})\/(\d{4})\s*<\/strong>([\s\S]*?)<\/tr>/);
  if (!rowMatch) return null;
  const dateISO = `${rowMatch[3]}-${rowMatch[2]}-${rowMatch[1]}`;
  const cells = rowMatch[4];
  const nums = [];
  const cellRe = /data-label="[^"]*"[^>]*>\s*([\d,]+)\s*</g;
  let cm;
  while ((cm = cellRe.exec(cells)) !== null && nums.length < 7) {
    nums.push(toNum(cm[1]));
  }
  if (nums.length < 6 || nums[0] == null) return null;
  return {
    source: 'ibjarates.com (previous dates)',
    dateISO,
    sessionLabel: paneId === 'tab-pm' ? 'PM' : 'AM',
    metals: {
      gold_999:   nums[0],
      gold_995:   nums[1],
      gold_916:   nums[2],
      gold_750:   nums[3],
      gold_585:   nums[4],
      silver_999: nums[5]
    }
  };
};

// ─── MAIN: left table first, else previous-dates (PM pane, else AM) ───
let result = parseTodayTable();
if (result) {
  console.log('✓ Using LEFT today table');
} else {
  console.log('Left table empty — falling back to Previous Dates table');
  result = parsePreviousDates('tab-pm') || parsePreviousDates('tab-am');
}

if (!result || !result.dateISO) {
  console.log('=== HTML DUMP (first 4000 chars) ===');
  console.log(html.substring(0, 4000));
  throw new Error('Could not parse rates from either the today table or the previous-dates table.');
}

const sessionLabel = result.sessionLabel; // 'AM' or 'PM'
const sessionLc = sessionLabel.toLowerCase();
console.log(`✓ Source: ${result.source} | Date: ${result.dateISO} | Session: ${sessionLabel} | Gold999: ${result.metals.gold_999} | Silver: ${result.metals.silver_999}`);

// ─── Build the rows array for the RPC call ───
const now2 = new Date().toISOString();
const rows = METALS
  .filter(m => result.metals[m.key] != null)
  .map(m => ({
    rate_date:  result.dateISO,
    metal_key:  `${m.key}_${sessionLc}`,
    rate_inr:   result.metals[m.key],
    source:     result.source,
    updated_at: now2
  }));

return [{
  json: {
    rows,
    session: sessionLabel,
    rate_date: result.dateISO,
    parsed_from: result.source
  }
}];

const input = $('Validate Rows Exist').first().json;
const count = Array.isArray(input.rows) ? input.rows.length : 0;

const now = new Date();
const istOffset = 5.5 * 60 * 60 * 1000;
const istNow = new Date(now.getTime() + istOffset);

return [{
  json: {
    status: 'success',
    message: 'IBJA rates replaced atomically (delete + insert in one transaction)',
    rows_written: count,
    session: input.session,
    rate_date: input.rate_date,
    timestamp_ist: istNow.toISOString().replace('T', ' ').substring(0, 19)
  }
}];
